-- Supabase runtime repository, payload columns and backend-only mutations.
begin;
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organisations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, name text not null, created_at timestamptz not null default now());
create table public.organisation_members (organisation_id uuid references public.organisations on delete cascade, user_id uuid references auth.users on delete cascade, role text not null check(role in ('owner','admin','member','viewer')), primary key(organisation_id,user_id));
create table public.projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, name text not null, description text, created_at timestamptz not null default now(), unique(id,owner_id));
create table public.uploaded_documents (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, project_id uuid, name text not null, storage_path text not null, content_hash text not null, size_bytes bigint not null check(size_bytes>=0), status text not null default 'queued', created_at timestamptz not null default now(), unique(id,owner_id), unique(owner_id,content_hash), foreign key(project_id,owner_id) references public.projects(id,owner_id));
create table public.document_metadata (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, document_id uuid not null, content jsonb not null default '{}', created_at timestamptz not null default now(), foreign key(document_id,owner_id) references public.uploaded_documents(id,owner_id) on delete cascade);
create table public.extracted_datasets (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, document_id uuid, name text not null, created_at timestamptz not null default now(), unique(id,owner_id), foreign key(document_id,owner_id) references public.uploaded_documents(id,owner_id) on delete cascade);
create table public.extracted_records (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, dataset_id uuid not null, values jsonb not null, source_location jsonb, confidence numeric check(confidence between 0 and 1), reviewed boolean not null default false, created_at timestamptz not null default now(), foreign key(dataset_id,owner_id) references public.extracted_datasets(id,owner_id) on delete cascade);
create table public.document_templates (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, document_id uuid, name text not null, created_at timestamptz not null default now(), unique(id,owner_id), foreign key(document_id,owner_id) references public.uploaded_documents(id,owner_id));
create table public.template_fields (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, template_id uuid not null, name text not null, configuration jsonb not null, created_at timestamptz not null default now(), foreign key(template_id,owner_id) references public.document_templates(id,owner_id) on delete cascade);
create table public.field_mappings (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, dataset_id uuid not null, template_id uuid not null, mapping jsonb not null, approved_at timestamptz, created_at timestamptz not null default now(), foreign key(dataset_id,owner_id) references public.extracted_datasets(id,owner_id), foreign key(template_id,owner_id) references public.document_templates(id,owner_id));
create table public.signatures (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, name text not null, storage_path text not null, is_default boolean not null default false, created_at timestamptz not null default now(), unique(id,owner_id));
create table public.generation_jobs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, template_id uuid not null, dataset_id uuid not null, status text not null default 'queued', progress jsonb not null default '{}', created_at timestamptz not null default now(), unique(id,owner_id), foreign key(template_id,owner_id) references public.document_templates(id,owner_id), foreign key(dataset_id,owner_id) references public.extracted_datasets(id,owner_id));
create table public.signing_authorisations (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, signature_id uuid not null, job_id uuid not null, authorised_at timestamptz not null default now(), scope jsonb not null, created_at timestamptz not null default now(), foreign key(signature_id,owner_id) references public.signatures(id,owner_id), foreign key(job_id,owner_id) references public.generation_jobs(id,owner_id));
create table public.generated_documents (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, job_id uuid not null, name text not null, storage_path text not null, verified_at timestamptz, created_at timestamptz not null default now(), foreign key(job_id,owner_id) references public.generation_jobs(id,owner_id) on delete cascade);
create table public.business_profiles (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, verified_information jsonb not null default '{}', created_at timestamptz not null default now());
create table public.tender_projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, document_id uuid not null, closing_at timestamptz, created_at timestamptz not null default now(), unique(id,owner_id), foreign key(document_id,owner_id) references public.uploaded_documents(id,owner_id));
create table public.tender_requirements (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, tender_id uuid not null, source_text text not null, status text not null default 'manual_review', evidence jsonb, created_at timestamptz not null default now(), foreign key(tender_id,owner_id) references public.tender_projects(id,owner_id) on delete cascade);
create table public.compliance_documents (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, document_id uuid not null, expires_at timestamptz, category text not null, created_at timestamptz not null default now(), foreign key(document_id,owner_id) references public.uploaded_documents(id,owner_id));
create table public.document_comparisons (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, source_ids uuid[] not null, changes jsonb not null, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, message text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.subscription_plans (id uuid primary key default gen_random_uuid(), name text not null unique, entitlements jsonb not null, provider_price_id text, active boolean not null default true);
create table public.user_subscriptions (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users on delete cascade, plan_id uuid not null references public.subscription_plans, provider_reference text unique, status text not null, expires_at timestamptz, created_at timestamptz not null default now());
-- Owner access remains strict. Team sharing requires separate audited policies.
do $$ declare t text; begin
foreach t in array array['organisations','projects','uploaded_documents','document_metadata','extracted_datasets','extracted_records','document_templates','template_fields','field_mappings','signatures','generation_jobs','signing_authorisations','generated_documents','business_profiles','tender_projects','tender_requirements','compliance_documents','document_comparisons','audit_logs','notifications','user_subscriptions'] loop
execute format('alter table public.%I enable row level security',t);
execute format('create index on public.%I(owner_id)',t);
execute format('create policy owner_read on public.%I for select to authenticated using (owner_id = auth.uid())',t);
if t not in ('audit_logs','user_subscriptions','signing_authorisations','generation_jobs','generated_documents') then
execute format('create policy owner_insert on public.%I for insert to authenticated with check (owner_id = auth.uid())',t);
execute format('create policy owner_update on public.%I for update to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid())',t);
execute format('create policy owner_delete on public.%I for delete to authenticated using (owner_id = auth.uid())',t);
end if;
end loop; end $$;
alter table public.profiles enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid());
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.organisation_members enable row level security;
create policy member_read on public.organisation_members for select to authenticated using(user_id=auth.uid());
alter table public.subscription_plans enable row level security;
create policy plans_read on public.subscription_plans for select to authenticated using(active);
insert into storage.buckets(id,name,public) values ('documents','documents',false),('signatures','signatures',false) on conflict(id) do nothing;
create policy private_file_read on storage.objects for select to authenticated using(bucket_id in ('documents','signatures') and (storage.foldername(name))[1]=auth.uid()::text);
create policy private_file_insert on storage.objects for insert to authenticated with check(bucket_id in ('documents','signatures') and (storage.foldername(name))[1]=auth.uid()::text);
create policy private_file_delete on storage.objects for delete to authenticated using(bucket_id in ('documents','signatures') and (storage.foldername(name))[1]=auth.uid()::text);
commit;
